insert into public.words (id, word, romanization, category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values

('141', '엠창', 'Em-Chang', 'slang', '심한 자기비하·비하성 욕설, 인생 낙오자를 가리키는 비속어',
$j${"en":"A harsh self-deprecating curse now used to call someone a loser","ja":"自虐的な誓いから来た、負け犬を意味する強い罵り言葉","es":"Una maldición autodespectiva ahora usada para llamar perdedor a alguien","vi":"Lời chửi tự hạ thấp bản thân, nay dùng để gọi ai đó là kẻ thất bại","de":"Ein selbstherabsetzender Fluch, der heute jemanden als Verlierer bezeichnet"}$j$::jsonb,
'[엠창]',
$j$[{"type":"명사","examples":[{"kor":"그렇게 쉬운 것도 못 하다니 완전 엠창이네.","eng":"Can't even do something that easy — total loser (em-chang).","ja":"あんな簡単なこともできないなんて完全に엠창だな。","es":"No poder hacer algo tan fácil… eres un perdedor total (em-chang).","vi":"Cái dễ vậy mà không làm được, đúng kiểu thất bại (em-chang).","de":"So etwas Einfaches nicht hinzukriegen — totaler Verlierer (em-chang)."}],"definition":"'이게 거짓말이면 우리 엄마는 창녀다'라는 극단적 자기비하식 맹세 표현의 줄임말('엄창'이 원형). 원래는 이런 맹세를 하는 사람의 처지를 비하하는 뜻이었으나, 많이 쓰이면서 의미가 무뎌져 지금은 '찌질이', '루저', '인생 패배자'와 비슷한 뜻의 심한 비속어로 쓰인다.","definition_i18n":{"en":"Short for '이게 거짓말이면 우리 엄마는 창녀다' (if this is a lie, my mom is a prostitute) — an extreme self-deprecating oath, originally '엄창'. It originally mocked the person swearing it, but through overuse the meaning dulled into a harsh insult roughly equivalent to 'loser' or 'pathetic failure.'","ja":"「이게 거짓말이면 우리 엄마는 창녀다(これが嘘なら俺の母は娼婦だ)」という極端な自虐的な誓いの言葉「엄창」が変化した略語。もとは誓いを立てる人自身を貶める意味だったが、多用されるうちに意味が薄れ、今は「負け犬」「ダメ人間」に近い強い侮辱語として使われる。","es":"Abreviatura de '이게 거짓말이면 우리 엄마는 창녀다' (si esto es mentira, mi madre es una prostituta) — un juramento autodespectivo extremo, originalmente '엄창'. Originalmente se burlaba de quien lo juraba, pero con el uso excesivo el significado se diluyó hasta convertirse en un insulto duro equivalente a 'perdedor' o 'fracasado patético'.","vi":"Viết tắt của '이게 거짓말이면 우리 엄마는 창녀다' (nếu đây là lời nói dối thì mẹ tôi là gái mại dâm) — một lời thề tự hạ thấp cực đoan, ban đầu là '엄창'. Ban đầu nhằm chế giễu chính người thề, nhưng qua lạm dụng nghĩa nhạt dần thành lời sỉ nhục nặng nề tương đương 'kẻ thua cuộc' hay 'kẻ thất bại thảm hại'.","de":"Kurzform für '이게 거짓말이면 우리 엄마는 창녀다' (wenn das eine Lüge ist, ist meine Mutter eine Prostituierte) — ein extremer selbstherabsetzender Schwur, ursprünglich '엄창'. Ursprünglich verspottete es die schwörende Person selbst, doch durch übermäßigen Gebrauch verblasste die Bedeutung zu einer harten Beleidigung, etwa gleichbedeutend mit 'Verlierer' oder 'erbärmlicher Versager'."}}]$j$::jsonb,
'디시인사이드·일간베스트 등 남초 온라인 커뮤니티에서 생긴 자기비하식 맹세 표현 ''엄창''에서 변형됐다. 최초 사용자는 확인되지 않으며, 지나치게 노골적인 욕설이라 커뮤니티 안에서도 순화 표현으로 자주 검열된다.',
$j${"en":"A variant of '엄창,' a self-deprecating oath phrase that emerged on male-dominated online communities like DC Inside and Ilbe. No individual coiner has been confirmed, and because it is such blatant profanity, it is often censored even within those communities.","ja":"DCインサイドや日刊ベストなど男性中心のオンラインコミュニティで生まれた自虐的な誓いの言葉「엄창」の変形。最初に使い始めた人物は確認されておらず、あまりに露骨な罵倒語のため、コミュニティ内でも伏字にされることが多い。","es":"Una variante de '엄창,' una frase de juramento autodespectivo surgida en comunidades en línea dominadas por hombres como DC Inside e Ilbe. No se ha confirmado quién la acuñó, y por ser una grosería tan flagrante, a menudo se censura incluso dentro de esas comunidades.","vi":"Biến thể của '엄창,' một cụm từ thề tự hạ thấp xuất hiện trên các cộng đồng mạng nam giới chiếm đa số như DC Inside và Ilbe. Chưa xác nhận được ai đặt ra, và vì là lời chửi quá trắng trợn nên thường bị kiểm duyệt ngay cả trong các cộng đồng đó.","de":"Eine Variante von '엄창,' einer selbstherabsetzenden Schwurformel, die in männerdominierten Online-Communitys wie DC Inside und Ilbe entstand. Kein einzelner Urheber ist bestätigt, und weil es sich um so unverhohlene Obszönität handelt, wird es selbst innerhalb dieser Communitys oft zensiert."}$j$::jsonb,
'매우 공격적인 비속어로, 상대를 심하게 비하하는 말이다. 실제 대화나 공개적 자리에서 쓰면 안 되고, 이 사전에는 뜻을 알아두어 인터넷에서 마주쳤을 때 이해하기 위한 목적으로만 수록한다.',
$j${"en":"An extremely aggressive insult that harshly demeans someone. Never use it in real conversation or in public — it is included here only so learners can recognize and understand it if they encounter it online.","ja":"相手を強く貶める非常に攻撃的な罵倒語。実際の会話や公の場では絶対に使ってはいけない。この辞典には、インターネットで見かけたときに意味を理解できるようにという目的のみで収録している。","es":"Un insulto extremadamente agresivo que degrada duramente a alguien. Nunca lo uses en una conversación real ni en público — se incluye aquí solo para que los estudiantes puedan reconocerlo y entenderlo si lo encuentran en internet.","vi":"Lời sỉ nhục cực kỳ hung hăng, hạ thấp nặng nề người khác. Tuyệt đối không dùng trong giao tiếp thực tế hay nơi công cộng — từ này được đưa vào đây chỉ để người học nhận ra và hiểu nghĩa khi gặp trên mạng.","de":"Eine extrem aggressive Beleidigung, die jemanden hart herabwürdigt. Niemals in echten Gesprächen oder in der Öffentlichkeit verwenden — es ist hier nur aufgenommen, damit Lernende es online erkennen und verstehen können."}$j$::jsonb,
